contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: caller is this contract when invoking c
    function run(address potentialRecipient, address callerAsOwner, uint128 deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= deposit);
        // Capture initial contract balance and owner
        uint256 beforeBalance = address(c).balance;
        address owner = c.owner(); if (__ESBMC_reverted()) return;

        // If this test contract is the owner, then withdrawAll should succeed and transfer full balance to recipient.
        // Otherwise the call must revert and balance must stay the same.
        bool reverted;
        // make the deciding call
        c.withdrawAll(potentialRecipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;

        // If this contract is the owner (c.owner() == address(this)) then the call must not revert
        // and the contract's balance must become zero (all funds transferred out).
        // If this contract is not the owner then the call must revert and the contract's balance must be unchanged.
        assert((owner == address(this) && !reverted && afterBalance == 0) || (owner != address(this) && reverted && afterBalance == beforeBalance));
    }

    // allow receiving Ether forwarded by C when withdrawAll succeeds
    receive() external payable {}
}

