    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address potentialRecipient, address callerAsOwner, uint128 deposit) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        uint256 beforeBalance = address(c).balance;
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        bool reverted;
        try c.withdrawAll(potentialRecipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance = address(c).balance;
        assertTrue((owner == address(this) && !reverted && afterBalance == 0) || (owner != address(this) && reverted && afterBalance == beforeBalance));
    }

